basic-example:
import { useState } from 'react';
import { DsDatePicker } from '@primasoftllc/design-system';

export function Example() {
  const [value, setValue] = useState('2026-10-19');
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDatePicker label="Дата обслуживания" value={value} onChange={setValue} hint="Календарная дата без времени."/>
    <output aria-live="polite">Выбрано: {value || 'не указано'}</output>
  </div>;
}

form-validation:
import { useState } from 'react';
import { DsDatePicker, DsButton } from '@primasoftllc/design-system';

export function Example() {
  const [result, setResult] = useState('');
  return <form style={{display:'flex',flexDirection:'column',gap:16}} onSubmit={event => {
    event.preventDefault();
    setResult('Сохранено: ' + new FormData(event.currentTarget).get('scheduled'));
  }} onReset={() => setResult('')}>
    <DsDatePicker label="Дата обслуживания" name="scheduled" defaultValue="2026-10-19"
      required min="2026-10-01" max="2026-10-31"
      hint="Допустимый интервал: 2026-10-01 — 2026-10-31."/>
    <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
      <DsButton type="submit">Сохранить</DsButton>
      <DsButton type="reset" tone="secondary">Сбросить</DsButton>
    </div>
    <span role="status">{result}</span>
  </form>;
}

