import { DsDatePicker } from '@primasoftllc/design-system';

export function Example() {
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDatePicker label="Подтверждённое значение" defaultValue="2026-10-19" readOnly hint="Изменение доступно после отмены подтверждения."/>
    <DsDatePicker label="Недоступное значение" defaultValue="2026-10-19" disabled hint="Недостаточно прав для изменения."/>
    <DsDatePicker label="Проверка сервером" defaultValue="2026-10-19" error="На эту дату нет свободных мест. Выберите другую."/>
  </div>;
}
